async function streamCozeChat(messages, onDelta) {
  if (!COZE_API_TOKEN || !COZE_BOT_ID) {
    throw new Error("LLM \u672A\u914D\u7F6E\uFF1A\u8BF7\u5728\u73AF\u5883\u53D8\u91CF\u4E2D\u8BBE\u7F6E COZE_API_TOKEN \u4E0E COZE_BOT_ID");
  }
  const resp = await fetch(`${COZE_API_BASE}/v3/chat`, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${COZE_API_TOKEN}`,
      "Content-Type": "application/json"
    },
    body: JSON.stringify({
      bot_id: COZE_BOT_ID,
      user_id: "wali-report",
      stream: true,
      auto_save_history: false,
      additional_messages: messages
    })
  });
  if (!resp.ok || !resp.body) {
    const errText = await resp.text().catch(() => "");
    throw new Error(`Coze API ${resp.status}: ${errText.slice(0, 200)}`);
  }
  const contentType = resp.headers.get("content-type") ?? "";
  if (contentType.includes("application/json")) {
    const data = await resp.json().catch(() => ({}));
    throw new Error(`Coze API${data.code ? ` code=${data.code}` : ""}: ${data.msg ?? "unknown error"}`);
  }
  const reader = resp.body.getReader();
  const decoder = new TextDecoder();
  let buf = "";
  let eventName = "";
  const handleLine = (rawLine) => {
    const line = rawLine.trimEnd();
    if (line.startsWith("event:")) {
      eventName = line.slice(6).trim();
      return;
    }
    if (!line.startsWith("data:")) return;
    const payload = line.slice(5).trim();
    if (!payload || payload === "[DONE]") return;
    let evt;
    try {
      evt = JSON.parse(payload);
    } catch {
      return;
    }
    if (eventName === "conversation.message.delta") {
      if (evt.type === "answer" && typeof evt.content === "string" && evt.content) {
        onDelta(evt.content);
      }
    } else if (eventName === "conversation.chat.failed" || eventName === "error") {
      const msg = evt.last_error?.msg ?? String(evt.msg ?? "chat failed");
      throw new Error(`Coze chat failed: ${msg}`);
    }
    eventName = "";
  };
  while (true) {
    const { done, value } = await reader.read();
    if (done) break;
    buf += decoder.decode(value, { stream: true });
    let idx;
    while ((idx = buf.indexOf("\n")) >= 0) {
      handleLine(buf.slice(0, idx));
      buf = buf.slice(idx + 1);
    }
  }
  if (buf.trim()) handleLine(buf);
}
async function streamReport(res, input, _forwardHeaders) {
  res.setHeader("Content-Type", "text/event-stream; charset=utf-8");
  res.setHeader("Cache-Control", "no-cache, no-store, no-transform, must-revalidate");
  res.setHeader("Connection", "keep-alive");
  res.setHeader("X-Accel-Buffering", "no");
  res.flushHeaders?.();
  let clientClosed = false;
  res.on("close", () => {
    clientClosed = true;
  });
  try {
    const messages = await buildMessages(input);
    await streamCozeChat(messages, (text) => {
      if (clientClosed || !text) return;
      res.write(`data: ${JSON.stringify({ text })}

`);
    });
    if (!clientClosed) res.write("data: [DONE]\n\n");
  } catch (e3) {
    const msg = e3 instanceof Error ? e3.message : "\u62A5\u544A\u751F\u6210\u5931\u8D25";
    console.error("[report] stream error:", msg);
    if (!clientClosed) {
      res.write(`data: ${JSON.stringify({ error: msg })}

`);
      res.write("data: [DONE]\n\n");
    }
  } finally {
    res.end();
  }
}

