// src/storage/database/seed.ts
async function ensurePhoneModelsSeeded() {
  const client2 = getSupabaseClient();
  try {
    const { count, error: error48 } = await client2.from("phone_models").select("id", { count: "exact", head: true });
    if (error48) throw error48;
    if ((count ?? 0) > 0) {
      console.log(`[seed] phone_models already has ${count} rows, skip seeding`);
      return;
    }
    console.log(`[seed] phone_models is empty, seeding ${SEED_PHONE_MODELS.length} models...`);
    const baseRows = SEED_PHONE_MODELS.map(({ upgrade_model_id, ...rest }) => rest);
    const { error: insertError } = await client2.from("phone_models").insert(baseRows);
    if (insertError) throw insertError;
    for (const model of SEED_PHONE_MODELS) {
      if (model.upgrade_model_id == null) continue;
      const { error: updateError } = await client2.from("phone_models").update({ upgrade_model_id: model.upgrade_model_id }).eq("id", model.id);
      if (updateError) throw updateError;
    }
    console.log(`[seed] phone_models seeded (${SEED_PHONE_MODELS.length} rows)`);
  } catch (err) {
    console.error("[seed] ensurePhoneModelsSeeded failed:", err);
  }
}

// functions-src/index.ts
var maxDuration = 60;
var bootstrap = null;
function ensureBootstrap() {
  if (!bootstrap) {
    bootstrap = ensurePhoneModelsSeeded().catch((error48) => {
      console.error("[bootstrap] seed failed:", error48);
    });
  }
  return bootstrap;
}
async function handler(req, res) {
  try {
    await ensureBootstrap();
    return await app_default(req, res);
  } catch (error48) {
    console.error("[handler] unhandled error:", error48);
    if (!res.headersSent) {
      res.status(500).json({
        error: "internal error",
        detail: error48 instanceof Error ? error48.message : String(error48)
      });
    } else {
      res.end();
    }
  }
}
